INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_09','V504','阮明',9,'好的，实在不好意思，是我疏忽了，耽误您时间了。','hǎo de ， shí zài bù hǎo yì sī ， shì wǒ shū hū le ， dān wù nín shí jiān le 。','Dạ vâng, em thật sự xin lỗi, tại em sơ suất nên làm mất thời gian của chị ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT505','SV1','咨询留学生居留许可有效时长与入境截止规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V505','SIT505','P1','suon_se','ban_chinh_thuc',NULL,'学生居留许可最长与学制同步，到期断签属于非法滞留，会产生罚款并影响后续再次来华签证。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_01','V505','阮明',1,'警官您好，我想咨询一下留学生居留许可的有效期问题。','jǐng guān nín hǎo ， wǒ xiǎng zī xún yī xià liú xué shēng jū liú xǔ kě de yǒu xiào qī wèn tí 。','Chào anh công an, em muốn hỏi về vấn đề thời hạn hiệu lực của giấy phép cư trú dành cho du học sinh ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_02','V505','辅警',2,'没问题，学生居留许可的时长是跟你的学制对应的，本科留学生一般一次批一年有效期。','méi wèn tí ， xué shēng jū liú xǔ kě de shí cháng shì gēn nǐ de xué zhì duì yìng de ， běn kē liú xué shēng yì bān yī cì pī yī nián yǒu xiào qī 。','Không vấn đề gì, thời hạn giấy phép cư trú của du học sinh sẽ tương ứng với thời gian học của em, du học sinh đại học thông thường mỗi lần cấp có hiệu lực một năm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_03','V505','阮明',3,'那我寒暑假回国，只要居留证没过期，来回出入境都没问题是吗？','nà wǒ hán shǔ jià huí guó ， zhǐ yào jū liú zhèng mò guò qī ， lái huí chū rù jìng dōu méi wèn tí shì ma ？','Vậy nếu em về nước dịp nghỉ đông nghỉ hè, chỉ cần thẻ cư trú chưa hết hạn thì đi lại xuất nhập cảnh nhiều lần đều không sao đúng không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_04','V505','辅警',4,'对，有效期内可以多次出入境，不用额外报备。但千万不能超期滞留，会有罚款和不良记录的。','duì ， yǒu xiào qī nèi kě yǐ duō cì chū rù jìng ， bù yòng é wài bào bèi 。 dàn qiān wàn bù néng chāo qī zhì liú ， huì yǒu fá kuǎn hé bù liáng jì lù de 。','Đúng vậy, trong thời hạn hiệu lực thì được xuất nhập cảnh nhiều lần, không cần báo cáo thêm gì cả. Nhưng tuyệt đối không được ở quá hạn, sẽ bị phạt tiền và có tiền sử xấu đấy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_05','V505','阮明',5,'了解了。那居留证快到期的话，最晚要提前多久申请续签？','liǎo jiě le 。 nà jū liú zhèng kuài dào qī de huà ， zuì wǎn yào tí qián duō jiǔ shēn qǐng xù qiān ？','Em hiểu rồi ạ. Vậy nếu thẻ cư trú sắp hết hạn thì chậm nhất phải xin gia hạn trước bao lâu ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_06','V505','辅警',6,'最好提前三十天提交申请，预留出审核周期，避免出现断签的情况。','zuì hǎo tí qián sān shí tiān tí jiāo shēn qǐng ， yù liú chū shěn hé zhōu qī ， bì miǎn chū xiàn duàn qiān de qíng kuàng 。','Tốt nhất nên nộp hồ sơ trước ba mươi ngày, để dành thời gian cho quá trình xét duyệt, tránh bị gián đoạn thời hạn cư trú.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_07','V505','阮明',7,'还有一个问题，我入境签证上有个最晚入境日期，那个是必须遵守的吗？','hái yǒu yí gè wèn tí ， wǒ rù jìng qiān zhèng shàng yǒu gè zuì wǎn rù jìng rì qī ， nà ge shì bì xū zūn shǒu de ma ？','Còn một vấn đề nữa, trên visa nhập cảnh của em có ghi ngày nhập cảnh muộn nhất, cái đó có bắt buộc phải tuân thủ không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_08','V505','辅警',8,'必须的，一定要在标注日期前入境，一旦逾期，这张签证就直接作废了。','bì xū de ， yí dìng yào zài biāo zhù rì qī qián rù jìng ， yí dàn yú qī ， zhè zhāng qiān zhèng jiù zhí jiē zuò fèi le 。','Bắt buộc chứ, nhất định phải nhập cảnh trước ngày ghi trên đó, một khi quá hạn thì visa này coi như bị hủy luôn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_09','V505','阮明',9,'嗯，所有规则我都记清楚了，谢谢您！','ń ， suǒ yǒu guī zé wǒ dōu jì qīng chǔ le ， xiè xiè nín ！','Dạ, tất cả các quy định em đã nhớ rõ rồi, em cảm ơn anh ạ!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT506','SV1','学校统一代办居留签证，补交缺失的白底证件照',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V506','SIT506','P1','twist','tuy_y',NULL,'出入境签证证件照有统一尺寸、底色标准，照相馆会区分普通证件照与涉外签证专用照。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_01','V506','老师',1,'阮明，等一下，你的签证材料还差一样东西。','ruǎn míng ， děng yí xià ， nǐ de qiān zhèng cái liào hái chà yī yàng dōng xī 。','Nguyễn Minh, khoan đã, hồ sơ xin visa của em còn thiếu một thứ nữa đấy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_02','V506','阮明',2,'啊？我上周不是已经把证件照交上去了吗？','a ？ wǒ shàng zhōu bú shì yǐ jīng bǎ zhèng jiàn zhào jiāo shàng qù le ma ？','Hả? Tuần trước em nộp ảnh thẻ rồi mà cô?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_03','V506','老师',3,'你上次交的是普通生活照，不符合出入境签证的照片标准，用不了。','nǐ shàng cì jiāo de shì pǔ tōng shēng huó zhào ， bù fú hé chū rù jìng qiān zhèng de zhào piān biāo zhǔn ， yòng bù liǎo 。','Lần trước em nộp là ảnh sinh hoạt bình thường, không đúng chuẩn ảnh dùng cho visa xuất nhập cảnh, không dùng được đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_04','V506','阮明',4,'这样啊……那需要什么样的照片？','zhè yàng a …… nà xū yào shén me yàng de zhào piān ？','Vậy à... thế cần ảnh kiểu gì ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_05','V506','老师',5,'得是小二寸的白底免冠证件照，专门用来办签证的那种。','dé shì xiǎo èr cùn de bái dǐ miǎn guān zhèng jiàn zhào ， zhuān mén yòng lái bàn qiān zhèng de nà zhǒng 。','Phải là ảnh thẻ cỡ 2 nhỏ, nền trắng, không đội mũ, loại chuyên dùng để làm visa ấy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_06','V506','阮明',6,'楼下的照相馆能拍吗？我怕拍出来还是不达标。','lóu xià de zhào xiàng guǎn néng pāi ma ？ wǒ pà pāi chū lái hái shì bù dá biāo 。','Tiệm ảnh dưới lầu chụp được không cô? Em sợ chụp xong lại không đạt chuẩn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_07','V506','老师',7,'可以的，你直接跟摄影师说，是留学生办居留许可用的，他们都知道统一规格。','kě yǐ de ， nǐ zhí jiē gēn shè yǐng shī shuō ， shì liú xué shēng bàn jū liú xǔ kě yòng de ， tā men dōu zhī dào tǒng yī guī gé 。','Được đấy, em cứ nói thẳng với thợ chụp là ảnh để du học sinh làm giấy phép cư trú, họ đều biết quy cách chung mà.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_08','V506','阮明',8,'行，那我现在立马下去拍。拍完直接拿给您，还需要补填别的表格吗？','xíng ， nà wǒ xiàn zài lì mǎ xià qù pāi 。 pāi wán zhí jiē ná gěi nín ， hái xū yào bǔ tián bié de biǎo gé ma ？','Dạ được, vậy em xuống chụp ngay bây giờ. Chụp xong em đem lên nộp cô luôn, có cần điền thêm giấy tờ gì nữa không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_09','V506','老师',9,'不用填表，就只交纸质照片就行，你其他的信息系统里都存档了。','bù yòng tián biǎo ， jiù zhǐ jiāo zhǐ zhì zhào piān jiù xíng ， nǐ qí tā de xìn xī xì tǒng lǐ dōu cún dàng le 。','Không cần điền gì cả, chỉ nộp ảnh giấy thôi là được, các thông tin khác của em hệ thống đã lưu hết rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_10','V506','阮明',10,'好嘞，我很快就回来！','hǎo lei ， wǒ hěn kuài jiù huí lái ！','Dạ vâng, em đi nhanh rồi quay lại ngay!','AM08') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT507','SV1','入境停留超期，前往出入境大厅办理逾期说明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V507','SIT507','P1','twist','chinh_thuc',NULL,'外籍人员在华签证超期属于非法滞留，会根据超期天数罚款，多次逾期会被限制入境。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_01','V507','阮明',1,'警官您好，我想来处理一下我的入境逾期问题。','jǐng guān nín hǎo ， wǒ xiǎng lái chǔ lǐ yī xià wǒ de rù jìng yú qī wèn tí 。','Chào anh công an, tôi muốn xử lý vấn đề nhập cảnh quá hạn của mình ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_02','V507','民警',2,'具体是什么情况？超期停留了多久，说一下原因。','jù tǐ shì shén me qíng kuàng ？ chāo qī tíng liú le duō jiǔ ， shuō yī xià yuán yīn 。','Cụ thể là tình huống thế nào? Quá hạn bao lâu rồi, anh nói rõ nguyên nhân xem.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_03','V507','阮明',3,'我之前出境旅游，本来按时返程，结果遇到航班大面积延误，最后在国内多停留了五天。','wǒ zhī qián chū jìng lǚ yóu ， běn lái àn shí fǎn chéng ， jié guǒ yù dào háng bān dà miàn jī yán wù ， zuì hòu zài guó nèi duō tíng liú le wǔ tiān 。','Trước đó tôi xuất cảnh du lịch, vốn định về đúng hạn, nhưng gặp phải chuyến bay bị hoãn trên diện rộng, nên cuối cùng ở lại trong nước thêm năm ngày.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_04','V507','民警',4,'我看一下你的材料，机票行程单、学校在读证明都带了吗？','wǒ kàn yī xià nǐ de cái liào ， jī piào xíng chéng dān 、 xué xiào zài dú zhèng míng dōu dài le ma ？','Để tôi xem hồ sơ của anh, vé máy bay, lịch trình chuyến đi, giấy xác nhận đang học của trường, anh mang đủ chưa?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_05','V507','阮明',5,'都带来了，这是我的行程单，确实是航班原因导致的延误。','dōu dài lái le ， zhè shì wǒ de xíng chéng dān ， què shí shì háng bān yuán yīn dǎo zhì de yán wù 。','Tôi mang đủ hết rồi, đây là lịch trình chuyến đi của tôi, đúng là do chuyến bay bị hoãn gây ra thật.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_06','V507','民警',6,'五天属于短期超期，十五天以内的逾期，只要书面说明情况就可以，不会加重处罚。要是超过十五天，处理就严格多了。','wǔ tiān shǔ yú duǎn qī chāo qī ， shí wǔ tiān yǐ nèi de yú qī ， zhǐ yào shū miàn shuō míng qíng kuàng jiù kě yǐ ， bú huì jiā zhòng chǔ fá 。 yào shì chāo guò shí wǔ tiān ， chǔ lǐ jiù yán gé duō le 。','Năm ngày thuộc dạng quá hạn ngắn, trong vòng mười lăm ngày thì chỉ cần làm bản tường trình bằng văn bản là được, không bị xử phạt nặng. Nếu quá mười lăm ngày thì xử lý sẽ nghiêm ngặt hơn nhiều.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_07','V507','阮明',7,'那我这次逾期，会留下不良记录吗？会不会影响我下次续签居留证？','nà wǒ zhè cì yú qī ， huì liú xià bù liáng jì lù ma ？ huì bú huì yǐng xiǎng wǒ xià cì xù qiān jū liú zhèng ？','Vậy lần quá hạn này có để lại hồ sơ xấu không anh? Có ảnh hưởng đến việc gia hạn thẻ cư trú lần sau của tôi không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_08','V507','民警',8,'你是首次违规，而且是客观航班延误原因，如实报备说明后，不会对你后续续签造成严重影响。','nǐ shì shǒu cì wéi guī ， ér qiě shì kè guān háng bān yán wù yuán yīn ， rú shí bào bèi shuō míng hòu ， bú huì duì nǐ hòu xù xù qiān zào chéng yán zhòng yǐng xiǎng 。','Anh là vi phạm lần đầu, với lại lý do là chuyến bay bị hoãn khách quan, sau khi khai báo trung thực thì sẽ không ảnh hưởng nghiêm trọng đến việc gia hạn sau này của anh đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_09','V507','阮明',9,'那就好。我需要手写一份逾期情况说明，然后签字上交是吗？','nà jiù hǎo 。 wǒ xū yào shǒu xiě yī fèn yú qī qíng kuàng shuō míng ， rán hòu qiān zì shàng jiāo shì ma ？','Vậy thì tốt quá. Tôi cần viết tay một bản tường trình tình hình quá hạn, rồi ký tên nộp lên phải không anh?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_10','V507','民警',10,'对的，写完核对好个人信息签字，再缴纳对应的逾期罚款就办结了。','duì de ， xiě wán hé duì hǎo gè rén xìn xī qiān zì ， zài jiǎo nà duì yìng de yú qī fá kuǎn jiù bàn jié le 。','Đúng rồi, viết xong kiểm tra lại thông tin cá nhân cho khớp rồi ký tên, sau đó nộp phạt quá hạn tương ứng là xong.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_11','V507','阮明',11,'好，我现在马上写，全力配合处理。','hǎo ， wǒ xiàn zài mǎ shàng xiě ， quán lì pèi hé chǔ lǐ 。','Vâng, tôi viết ngay bây giờ, sẽ phối hợp hết mình để xử lý ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT508','SV1','咨询单人宿舍住宿登记如何录入居留系统',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V508','SIT508','P1','suon_se','tuy_y',NULL,'所有外籍居住人员必须完成住宿登记，校内宿舍由宿管开具登记证明，校外租房由房东陪同社区备案。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_01','V508','阮明',1,'阿姨，想问个事，我住的是单人宿舍，住宿登记要怎么弄啊？办签证要用。','ā yí ， xiǎng wèn gè shì ， wǒ zhù de shì dān rén sù shè ， zhù sù dēng jì yào zěn me nòng a ？ bàn qiān zhèng yào yòng 。','Cô ơi, con hỏi cái này chút, con ở phòng ký túc xá một người, đăng ký lưu trú phải làm thế nào ạ? Con cần để làm visa.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_02','V508','宿管阿姨',2,'简单，我这边直接给你打印住宿登记单，盖宿舍楼的公章就可以用了。','jiǎn dān ， wǒ zhè biān zhí jiē gěi nǐ dǎ yìn zhù sù dēng jì dān ， gài sù shè lóu de gōng zhāng jiù kě yǐ yòng le 。','Đơn giản mà, cô in ngay cho con tờ đăng ký lưu trú, đóng dấu của khu ký túc xá là dùng được luôn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_03','V508','阮明',3,'那单人宿舍和多人宿舍的单子是一样的吗？我怕格式不对用不了。','nà dān rén sù shè hé duō rén sù shè de dān zi shì yī yàng de ma ？ wǒ pà gé shì bú duì yòng bù liǎo 。','Vậy tờ đăng ký của phòng một người với phòng nhiều người có giống nhau không cô? Con sợ sai mẫu thì không dùng được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_04','V508','宿管阿姨',4,'单据都是通用的，你是单人住，我就在人数那一栏填“单人”就行，不影响。','dān jù dōu shì tōng yòng de ， nǐ shì dān rén zhù ， wǒ jiù zài rén shù nà yī lán tián “ dān rén ” jiù xíng ， bù yǐng xiǎng 。','Mẫu đơn dùng chung hết, con ở một mình thì cô ghi vào ô số người là "một người" là được, không ảnh hưởng gì đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_05','V508','阮明',5,'明白啦，那我拿到单子直接去出入境大厅交材料就行？','míng bái la ， nà wǒ ná dào dān zi zhí jiē qù chū rù jìng dà tīng jiāo cái liào jiù xíng ？','Dạ con hiểu rồi, vậy con cầm tờ này đến thẳng phòng xuất nhập cảnh nộp hồ sơ là được ạ?','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_06','V508','宿管阿姨',6,'对，这张单子就是证明你在校合法住宿的关键材料，办居留必须要的。','duì ， zhè zhāng dān zi jiù shì zhèng míng nǐ zài xiào hé fǎ zhù sù de guān jiàn cái liào ， bàn jū liú bì xū yào de 。','Đúng vậy, tờ giấy này chính là giấy tờ quan trọng chứng minh con ở trọ hợp pháp trong trường, làm cư trú bắt buộc phải có đấy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_07','V508','阮明',7,'那麻烦阿姨帮我打印一份呗，我下午就去办签证。','nà má fán ā yí bāng wǒ dǎ yìn yī fèn bei ， wǒ xià wǔ jiù qù bàn qiān zhèng 。','Vậy phiền cô in giúp con một bản nhé, chiều nay con đi làm visa luôn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT509','SV2','居留许可快到期，提前咨询续办流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V509','SIT509','P1','suon_se','ban_chinh_thuc',NULL,'居留续签不能使用过期住宿登记、旧流水，所有辅助材料要求近期开具，保证信息实时有效。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_01','V509','阮明',1,'老师，我的居留许可还有四十天就到期了，我想提前问问续签的流程。','lǎo shī ， wǒ de jū liú xǔ kě hái yǒu sì shí tiān jiù dào qī le ， wǒ xiǎng tí qián wèn wèn xù qiān de liú chéng 。','Thưa cô, thẻ cư trú của em còn bốn mươi ngày nữa là hết hạn, em muốn hỏi trước về quy trình gia hạn ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_02','V509','老师',2,'可以的，你提前准备刚好。首先要去学院开在读证明，然后备好银行存款流水。','kě yǐ de ， nǐ tí qián zhǔn bèi gāng hǎo 。 shǒu xiān yào qù xué yuàn kāi zài dú zhèng míng ， rán hòu bèi hǎo yín háng cún kuǎn liú shuǐ 。','Được chứ, em chuẩn bị trước như vậy là vừa đúng lúc. Trước tiên em cần lên khoa xin giấy xác nhận đang học, sau đó chuẩn bị sao kê số dư ngân hàng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_03','V509','阮明',3,'存款流水有要求吗？需要多少钱、存多久？','cún kuǎn liú shuǐ yǒu yāo qiú ma ？ xū yào duō shǎo qián 、 cún duō jiǔ ？','Sao kê số dư có yêu cầu gì không cô? Cần bao nhiêu tiền, gửi trong bao lâu ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_04','V509','老师',4,'留学生续签，建议准备不低于一万元的活期流水，最好是连续三个月以上的记录，更稳妥。','liú xué shēng xù qiān ， jiàn yì zhǔn bèi bù dī yú yī wàn yuán de huó qī liú shuǐ ， zuì hǎo shì lián xù sān gè yuè yǐ shàng de jì lù ， gèng wěn tuǒ 。','Du học sinh gia hạn thì nên chuẩn bị sao kê tài khoản thanh toán không dưới mười nghìn tệ, tốt nhất là có số dư liên tục từ ba tháng trở lên, sẽ chắc chắn hơn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_05','V509','阮明',5,'那我上次办签证的旧住宿登记单还能用吗？不想再重新开了。','nà wǒ shàng cì bàn qiān zhèng de jiù zhù sù dēng jì dān hái néng yòng ma ？ bù xiǎng zài chóng xīn kāi le 。','Vậy tờ đăng ký lưu trú cũ em dùng lần trước còn dùng được không ạ? Em không muốn xin lại nữa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_06','V509','老师',6,'不行哦，续签要求很严格，必须是近一个月新开具的登记单，旧的已经失效了。','bù xíng ó ， xù qiān yāo qiú hěn yán gé ， bì xū shì jìn yí gè yuè xīn kāi jù de dēng jì dān ， jiù de yǐ jīng shī xiào le 。','Không được đâu, yêu cầu gia hạn rất nghiêm ngặt, phải là tờ đăng ký mới cấp trong vòng một tháng gần đây, tờ cũ hết hiệu lực rồi.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_07','V509','阮明',7,'懂了。那我材料全部备齐之后，线上预约号就能直接去办了吧？','dǒng le 。 nà wǒ cái liào quán bù bèi qí zhī hòu ， xiàn shàng yù yuē hào jiù néng zhí jiē qù bàn le ba ？','Em hiểu rồi. Vậy sau khi chuẩn bị đủ hồ sơ, em đặt lịch hẹn trực tuyến rồi đi làm luôn được phải không cô?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_08','V509','老师',8,'对，线上预约可以优先办理，不用排队。没预约的话，只能现场等空位，很耗时间。','duì ， xiàn shàng yù yuē kě yǐ yōu xiān bàn lǐ ， bù yòng pái duì 。 méi yù yuē de huà ， zhǐ néng xiàn chǎng děng kòng wèi ， hěn hào shí jiān 。','Đúng vậy, đặt lịch hẹn trực tuyến sẽ được ưu tiên xử lý, không cần xếp hàng. Nếu không đặt lịch thì chỉ có thể chờ chỗ trống tại chỗ thôi, rất mất thời gian.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_09','V509','阮明',9,'好，我尽快把所有材料整理齐全，避免到期来不及办理。','hǎo ， wǒ jǐn kuài bǎ suǒ yǒu cái liào zhěng lǐ qí quán ， bì miǎn dào qī lái bù jí bàn lǐ 。','Dạ, em sẽ nhanh chóng chuẩn bị đầy đủ hồ sơ, tránh để gần hết hạn mà không kịp làm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT510','SV2','续签证时银行存款证明余额不足，需重新开流水',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V510','SIT510','P1','that_bai_nhe','chinh_thuc',NULL,'留学生续签居留许可有活期存款最低额度要求，出入境只认可活期账户流水，定期、理财不计入审核余额。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_01','V510','阮明',1,'您好，我来递交居留续签的材料，麻烦您帮我核对一下。','nín hǎo ， wǒ lái dì jiāo jū liú xù qiān de cái liào ， má fán nín bāng wǒ hé duì yī xià 。','Chào anh, tôi đến nộp hồ sơ gia hạn thẻ cư trú, phiền anh kiểm tra giúp tôi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_02','V510','工作人员',2,'我看一下你的银行流水……不好意思，月末活期余额不够一万，达不到签证审核标准。','wǒ kàn yī xià nǐ de yín háng liú shuǐ …… bù hǎo yì sī ， yuè mò huó qī yú é bù gòu yī wàn ， dá bú dào qiān zhèng shěn hé biāo zhǔn 。','Để tôi xem sao kê ngân hàng của anh một chút... Xin lỗi, số dư tài khoản thanh toán cuối tháng không đủ mười nghìn, chưa đạt tiêu chuẩn xét duyệt visa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_03','V510','阮明',3,'啊？可是我卡里有定期存款，能不能把定期单一起交上去，当作资产证明？','a ？ kě shì wǒ kǎ lǐ yǒu dìng qī cún kuǎn ， néng bù néng bǎ dìng qī dān yī qǐ jiāo shàng qù ， dàng zuò zī chǎn zhèng míng ？','Hả? Nhưng thẻ tôi có tiền gửi tiết kiệm kỳ hạn, có thể nộp kèm sổ tiết kiệm đó để làm chứng minh tài sản không ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_04','V510','工作人员',4,'不可以的，系统只认可活期账户的实时余额，定期、理财这些都不算数。','bù kě yǐ de ， xì tǒng zhǐ rèn kě huó qī zhàng hù de shí shí yú é ， dìng qī 、 lǐ cái zhè xiē dōu bù suàn shù 。','Không được, hệ thống chỉ công nhận số dư thực tế của tài khoản thanh toán thôi, tiền gửi kỳ hạn hay đầu tư gì đó đều không tính.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_05','V510','阮明',5,'这样啊。那我现在转钱进去，明天重新打流水再来办理可以吗？','zhè yàng a 。 nà wǒ xiàn zài zhuǎn qián jìn qù ， míng tiān chóng xīn dǎ liú shuǐ zài lái bàn lǐ kě yǐ ma ？','Vậy à. Vậy giờ tôi chuyển tiền vào, mai in lại sao kê rồi đến làm lại được không ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_06','V510','工作人员',6,'可以的，资金入账后建议隔天再打印流水，数据才会更新完整，之后重新取号递交就行。','kě yǐ de ， zī jīn rù zhàng hòu jiàn yì gé tiān zài dǎ yìn liú shuǐ ， shù jù cái huì gēng xīn wán zhěng ， zhī hòu chóng xīn qǔ hào dì jiāo jiù xíng 。','Được chứ, sau khi tiền vào tài khoản thì nên đợi qua ngày hôm sau in sao kê, dữ liệu mới cập nhật đầy đủ, sau đó lấy số nộp lại là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_07','V510','阮明',7,'好，那我今天先把其他材料带回去，明天补齐资金再来。','hǎo ， nà wǒ jīn tiān xiān bǎ qí tā cái liào dài huí qù ， míng tiān bǔ qí zī jīn zài lái 。','Vâng, vậy hôm nay tôi mang các giấy tờ khác về trước, mai bổ sung tiền xong rồi quay lại.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_08','V510','工作人员',8,'提醒你一下，流水打印当天，不要大额转出资金，不然余额又不达标了。','tí xǐng nǐ yī xià ， liú shuǐ dǎ yìn dàng tiān ， bú yào dà é zhuǎn chū zī jīn ， bù rán yú é yòu bù dá biāo le 。','Nhắc anh luôn, ngày in sao kê thì đừng chuyển tiền ra số lượng lớn, không lại không đủ số dư nữa đấy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_09','V510','阮明',9,'我记住了，谢谢您的提醒。','wǒ jì zhù le ， xiè xiè nín de tí xǐng 。','Tôi nhớ rồi, cảm ơn anh đã nhắc nhở.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT511','SV2','在校出勤率不够，学校不给开具签证在读证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V511','SIT511','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内高校对留学生出勤有硬性考核，出勤率不达标学校有权拒开在读证明，无法办理居留续签，严重者会要求限期离境。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_01','V511','阮明',1,'辅导员您好，我要办居留续签，需要开在读证明，麻烦您帮我办理一下。','fǔ dǎo yuán nín hǎo ， wǒ yào bàn jū liú xù qiān ， xū yào kāi zài dú zhèng míng ， má fán nín bāng wǒ bàn lǐ yī xià 。','Chào thầy, em cần làm gia hạn thẻ cư trú nên cần xin giấy xác nhận đang học, phiền thầy giúp em ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_02','V511','辅导员',2,'我查一下你的出勤记录……你这学期旷课次数超标，出勤率没达到学校的硬性标准，暂时开不了。','wǒ chá yī xià nǐ de chū qín jì lù …… nǐ zhè xué qī kuàng kè cì shù chāo biāo ， chū qín lǜ méi dá dào xué xiào de yìng xìng biāo zhǔn ， zàn shí kāi bù liǎo 。','Để thầy kiểm tra chuyên cần của em... học kỳ này em nghỉ học vượt quá số buổi cho phép, tỷ lệ chuyên cần không đạt chuẩn của trường, tạm thời chưa cấp được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_03','V511','阮明',3,'老师，我之前缺课都是因为身体不舒服，我有医院的病假单啊！','lǎo shī ， wǒ zhī qián quē kè dōu shì yīn wèi shēn tǐ bù shū fú ， wǒ yǒu yī yuàn de bìng jià dān a ！','Thầy ơi, trước đó em nghỉ học đều là vì bị ốm mệt trong người, em có giấy nghỉ ốm của bệnh viện mà!','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_04','V511','辅导员',4,'我知道你有单据，但学校规定病假必须提前报备，事后补交的单据，不算合规请假，没办法抵消缺勤记录。','wǒ zhī dào nǐ yǒu dān jù ， dàn xué xiào guī dìng bìng jià bì xū tí qián bào bèi ， shì hòu bǔ jiāo de dān jù ， bù suàn hé guī qǐng jià ， méi bàn fǎ dǐ xiāo quē qín jì lù 。','Thầy biết em có giấy tờ, nhưng quy định của trường là xin nghỉ ốm phải báo trước, giấy tờ bổ sung sau khi đã nghỉ thì không tính là xin phép hợp lệ, không thể trừ vào số buổi vắng được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_05','V511','阮明',5,'那现在还有补救的办法吗？我真的急需这份证明办签证。','nà xiàn zài hái yǒu bǔ jiù de bàn fǎ ma ？ wǒ zhēn de jí xū zhè fèn zhèng míng bàn qiān zhèng 。','Vậy giờ có cách nào khắc phục không thầy? Em thực sự đang rất cần giấy này để làm visa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_06','V511','辅导员',6,'你接下来一个月全程满勤、不缺一节课，月末核查出勤合格后，我才能给你开证明。','nǐ jiē xià lái yí gè yuè quán chéng mǎn qín 、 bù quē yī jié kè ， yuè mò hé chá chū qín hé gé hòu ， wǒ cái néng gěi nǐ kāi zhèng míng 。','Em phải đi học đầy đủ, không vắng buổi nào trong một tháng tới, đến cuối tháng kiểm tra chuyên cần đạt yêu cầu thì thầy mới cấp giấy cho em được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_07','V511','阮明',7,'可是我的签证马上就到期了，等一个月的话，肯定会断签的！','kě shì wǒ de qiān zhèng mǎ shàng jiù dào qī le ， děng yí gè yuè de huà ， kěn dìng huì duàn qiān de ！','Nhưng visa của em sắp hết hạn rồi, đợi một tháng nữa thì chắc chắn bị đứt visa mất!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_08','V511','辅导员',8,'别急，我帮你开一份特殊情况说明，你先拿着去出入境，申请短期缓冲受理，先稳住签证时效。','bié jí ， wǒ bāng nǐ kāi yī fèn tè shū qíng kuàng shuō míng ， nǐ xiān ná zhe qù chū rù jìng ， shēn qǐng duǎn qī huǎn chōng shòu lǐ ， xiān wěn zhù qiān zhèng shí xiào 。','Đừng lo, thầy sẽ viết cho em một bản giải trình tình huống đặc biệt, em cầm cái đó đến phòng xuất nhập cảnh xin gia hạn xử lý tạm thời, giữ ổn định hiệu lực visa trước đã.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_09','V511','阮明',9,'太感谢您了！我之后一定好好上课，再也不缺勤了。','tài gǎn xiè nín le ！ wǒ zhī hòu yí dìng hǎo hǎo shàng kè ， zài yě bù quē qín le 。','Em cảm ơn thầy nhiều lắm ạ! Sau này em nhất định sẽ đi học chăm chỉ, không nghỉ học nữa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT512','SV2','咨询寒暑假居留延期是否需要额外材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V512','SIT512','P1','suon_se','tuy_y',NULL,'留学生寒暑假留校，续签必须额外提交加盖学院公章的留校申请，证明假期在校学习安排。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_01','V512','阮明',1,'警官，问一下哈，我寒暑假不回国，留校的话续签材料和平时一样吗？','jǐng guān ， wèn yī xià hā ， wǒ hán shǔ jià bù huí guó ， liú xiào de huà xù qiān cái liào hé píng shí yī yàng ma ？','Anh công an ơi, em hỏi chút, dịp nghỉ hè nghỉ đông em không về nước, ở lại trường thì hồ sơ gia hạn có giống bình thường không ạ?','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_02','V512','辅警',2,'大体材料都一样，就多一份东西，需要学院的寒暑假留校申请书。','dà tǐ cái liào dōu yī yàng ， jiù duō yī fèn dōng xī ， xū yào xué yuàn de hán shǔ jià liú xiào shēn qǐng shū 。','Về cơ bản hồ sơ giống nhau, chỉ thêm một thứ thôi, cần đơn xin ở lại trường dịp nghỉ hè nghỉ đông do khoa cấp.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_03','V512','阮明',3,'申请书我手写一份可以吗？','shēn qǐng shū wǒ shǒu xiě yī fèn kě yǐ ma ？','Đơn đó em viết tay được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_04','V512','辅警',4,'不行，得打印填写完整，再去国际处盖章，手写的没有公章，审核不通过。','bù xíng ， dé dǎ yìn tián xiě wán zhěng ， zài qù guó jì chù gài zhāng ， shǒu xiě de méi yǒu gōng zhāng ， shěn hé bù tōng guò 。','Không được, phải in ra điền đầy đủ rồi đem lên phòng quốc tế đóng dấu, viết tay không có con dấu thì không qua được xét duyệt đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_05','V512','阮明',5,'哦，那有效期还是正常一年吗？不会只给到开学吧？','ó ， nà yǒu xiào qī hái shì zhèng cháng yī nián ma ？ bú huì zhǐ gěi dào kāi xué ba ？','À vậy hạn hiệu lực vẫn là một năm bình thường chứ ạ? Không phải chỉ đến ngày khai giảng thôi đúng không?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_06','V512','辅警',6,'放心，统一按学制批一年，不受寒暑假留校的影响。','fàng xīn ， tǒng yī àn xué zhì pī yī nián ， bù shòu hán shǔ jià liú xiào de yǐng xiǎng 。','Yên tâm đi, đều cấp một năm theo học chế, không bị ảnh hưởng gì bởi việc ở lại trường dịp nghỉ hè nghỉ đông cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_07','V512','阮明',7,'行，我清楚了，回去马上打印盖章。','xíng ， wǒ qīng chǔ le ， huí qù mǎ shàng dǎ yìn gài zhāng 。','Dạ, em rõ rồi, về là in với đóng dấu ngay.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT513','SV2','校外租房居住，房东不配合办理住宿登记单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V513','SIT513','P1','twist','ban_chinh_thuc',NULL,'出租房屋房东有法定义务配合外籍租客完成社区住宿备案，拒不配合社区可依法约谈整改。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_01','V513','阮明',1,'网格员您好，我想咨询一下校外住宿备案的事，我的房东一直不肯配合我办理。','wǎng gé yuán nín hǎo ， wǒ xiǎng zī xún yī xià xiào wài zhù sù bèi àn de shì ， wǒ de fáng dōng yì zhí bù kěn pèi hé wǒ bàn lǐ 。','Chào anh cán bộ khu phố, tôi muốn hỏi về việc đăng ký lưu trú ngoài trường, chủ nhà tôi cứ không chịu phối hợp làm giúp tôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_02','V513','网格员',2,'他是为什么不愿意配合？是有什么顾虑吗？','tā shì wèi shén me bù yuàn yì pèi hé ？ shì yǒu shén me gù lǜ ma ？','Vì sao chủ nhà không chịu phối hợp? Có vướng mắc gì à?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_03','V513','阮明',3,'房东说备案要上交房产证复印件，担心个人信息泄露，死活不同意。','fáng dōng shuō bèi àn yào shàng jiāo fáng chǎn zhèng fù yìn jiàn ， dān xīn gè rén xìn xī xiè lòu ， sǐ huó bù tóng yì 。','Chủ nhà bảo đăng ký phải nộp bản sao giấy chứng nhận quyền sở hữu nhà, sợ lộ thông tin cá nhân nên nhất quyết không đồng ý.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_04','V513','网格员',4,'我懂了。你跟他说一下，外籍租客住宿备案是国家法定要求，房东有义务配合，不是可办可不办的。','wǒ dǒng le 。 nǐ gēn tā shuō yī xià ， wài jí zū kè zhù sù bèi àn shì guó jiā fǎ dìng yāo qiú ， fáng dōng yǒu yì wù pèi hé ， bú shì kě bàn kě bù bàn de 。','Tôi hiểu rồi. Anh nói với chủ nhà giúp tôi là đăng ký lưu trú cho người thuê nước ngoài là quy định pháp luật của nhà nước, chủ nhà có nghĩa vụ phối hợp, không phải muốn làm thì làm không muốn thì thôi đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_05','V513','阮明',5,'我跟他说了好几次，他还是不愿意到场，那我还有别的办法可以办登记吗？','wǒ gēn tā shuō le hǎo jǐ cì ， tā hái shì bù yuàn yì dào chǎng ， nà wǒ hái yǒu bié de bàn fǎ kě yǐ bàn dēng jì ma ？','Tôi nói với anh ấy mấy lần rồi, anh ấy vẫn không chịu có mặt, vậy còn cách nào khác để đăng ký được không anh?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_06','V513','网格员',6,'你不用自己沟通了，我上门去跟房东劝导沟通。要是还不配合，我们会下发书面整改告知单。','nǐ bù yòng zì jǐ gōu tōng le ， wǒ shàng mén qù gēn fáng dōng quàn dǎo gōu tōng 。 yào shì hái bù pèi hé ， wǒ men huì xià fā shū miàn zhěng gǎi gào zhī dān 。','Anh không cần tự trao đổi nữa, tôi sẽ đến tận nơi khuyên nhủ chủ nhà. Nếu vẫn không phối hợp, chúng tôi sẽ ban hành thông báo yêu cầu chỉnh sửa bằng văn bản.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_07','V513','阮明',7,'那太好了！我现在就在出租屋这边等着，您今天方便过来吗？','nà tài hǎo le ！ wǒ xiàn zài jiù zài chū zū wū zhè biān děng zhe ， nín jīn tiān fāng biàn guò lái ma ？','Vậy thì tốt quá! Giờ tôi đang ở nhà thuê đây, hôm nay anh tiện đến được không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_08','V513','网格员',8,'可以，我半小时内到现场，带备案表格过来，顺便核验房屋信息、拍照留存。','kě yǐ ， wǒ bàn xiǎo shí nèi dào xiàn chǎng ， dài bèi àn biǎo gé guò lái ， shùn biàn hé yàn fáng wū xìn xī 、 pāi zhào liú cún 。','Được, tôi sẽ đến nơi trong nửa tiếng nữa, mang theo mẫu đăng ký, tiện thể kiểm tra thông tin nhà và chụp ảnh lưu lại.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_09','V513','阮明',9,'真的麻烦您了，没有这个登记单，我根本没办法续办居留签证。','zhēn de má fán nín le ， méi yǒu zhè ge dēng jì dān ， wǒ gēn běn méi bàn fǎ xù bàn jū liú qiān zhèng 。','Thật sự phiền anh quá, không có tờ đăng ký này thì tôi hoàn toàn không thể gia hạn được visa cư trú.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT514','SV2','续居留预约号约满，咨询线下现场取号方案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V514','SIT514','P1','twist','tuy_y',NULL,'出入境线上预约号资源紧张，线下应急号数量有限，仅针对签证续签人群，新办居留不开放线下现场号。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_01','V514','阮明',1,'你好，我想办居留续签，但是线上近七天的预约号全部约满了，根本抢不到。','nǐ hǎo ， wǒ xiǎng bàn jū liú xù qiān ， dàn shì xiàn shàng jìn qī tiān de yù yuē hào quán bù yuē mǎn le ， gēn běn qiǎng bú dào 。','Chào chị, em muốn gia hạn thẻ tạm trú, nhưng số hẹn online trong gần bảy ngày tới đã kín hết rồi, không tài nào giành được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_02','V514','引导员',2,'正常的，线上号源特别紧张。不过我们大厅每天会留少量的线下应急号。','zhèng cháng de ， xiàn shàng hào yuán tè bié jǐn zhāng 。 bù guò wǒ men dà tīng měi tiān huì liú shǎo liàng de xiàn xià yìng jí hào 。','Bình thường thôi, số online lúc nào cũng căng lắm. Nhưng sảnh mình mỗi ngày vẫn để lại một ít số khẩn cấp làm trực tiếp.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_03','V514','阮明',3,'线下号是直接来就能取吗？几点开始发放呀？','xiàn xià hào shì zhí jiē lái jiù néng qǔ ma ？ jǐ diǎn kāi shǐ fā fàng ya ？','Số làm trực tiếp là đến là lấy được luôn hả? Mấy giờ bắt đầu phát vậy?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_04','V514','引导员',4,'早上八点开门准时放号，数量有限，发完就没了，不会额外追加。','zǎo shàng bā diǎn kāi mén zhǔn shí fàng hào ， shù liàng yǒu xiàn ， fā wán jiù méi le ， bú huì é wài zhuī jiā 。','Tám giờ sáng mở cửa là phát số đúng giờ luôn, số lượng có hạn, hết là hết, không bổ sung thêm đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_05','V514','阮明',5,'那我问清楚，这个现场号只能办续签对吧？首次办居留不能用？','nà wǒ wèn qīng chǔ ， zhè ge xiàn chǎng hào zhǐ néng bàn xù qiān duì ba ？ shǒu cì bàn jū liú bù néng yòng ？','Vậy em hỏi rõ luôn nha, số trực tiếp này chỉ dùng để gia hạn thôi đúng không? Làm thẻ tạm trú lần đầu không dùng được à?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_06','V514','引导员',6,'没错，只针对续签业务，首次办理必须线上预约，没有现场通道。','méi cuò ， zhǐ zhēn duì xù qiān yè wù ， shǒu cì bàn lǐ bì xū xiàn shàng yù yuē ， méi yǒu xiàn chǎng tōng dào 。','Đúng rồi, chỉ áp dụng cho gia hạn thôi, làm lần đầu bắt buộc phải hẹn online, không có cửa làm trực tiếp đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_07','V514','阮明',7,'明白了，那我明天早点来，七点半过来排队应该能抢到吧。','míng bái le ， nà wǒ míng tiān zǎo diǎn lái ， qī diǎn bàn guò lái pái duì yīng gāi néng qiǎng dào ba 。','Em hiểu rồi, vậy mai em đến sớm hơn, khoảng bảy rưỡi ra xếp hàng chắc giành được số.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT515','SV2','签证办理期间护照上交，申请临时出行证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V515','SIT515','P1','suon_se','chinh_thuc',NULL,'护照上交出入境办理签证期间，无法乘坐交通、入住酒店，必须申请临时出行证明作为替代身份证件。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_01','V515','阮明',1,'您好，我的护照已经上交办理居留续签了，但是我周末要出门短途出行，想问问有没有替代证件能用？','nín hǎo ， wǒ de hù zhào yǐ jīng shàng jiāo bàn lǐ jū liú xù qiān le ， dàn shì wǒ zhōu mò yào chū mén duǎn tú chū xíng ， xiǎng wèn wèn yǒu méi yǒu tì dài zhèng jiàn néng yòng ？','Chào anh/chị, hộ chiếu của em đã nộp để làm thủ tục gia hạn tạm trú rồi, nhưng cuối tuần em có việc phải đi ra ngoài ngắn ngày, không biết có giấy tờ thay thế nào dùng được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_02','V515','工作人员',2,'有的，这种情况可以办理《外国人临时出行证明》。','yǒu de ， zhè zhǒng qíng kuàng kě yǐ bàn lǐ 《 wài guó rén lín shí chū xíng zhèng míng 》。','Có ạ, trường hợp này có thể làm "Giấy chứng nhận đi lại tạm thời cho người nước ngoài".',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_03','V515','阮明',3,'那这个证明有效期是多久啊？','nà zhè ge zhèng míng yǒu xiào qī shì duō jiǔ a ？','Vậy giấy chứng nhận này có hiệu lực bao lâu ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_04','V515','工作人员',4,'有效期统一七天，足够你短期出行使用了。','yǒu xiào qī tǒng yī qī tiān ， zú gòu nǐ duǎn qī chū xíng shǐ yòng le 。','Thời hạn thống nhất là bảy ngày, đủ để bạn đi lại ngắn ngày rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_05','V515','阮明',5,'办理的话需要准备什么材料？我提前备好。','bàn lǐ de huà xū yào zhǔn bèi shén me cái liào ？ wǒ tí qián bèi hǎo 。','Vậy làm giấy này cần chuẩn bị giấy tờ gì ạ? Để em chuẩn bị trước.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_06','V515','工作人员',6,'只需要交一张白底证件照，再填写清楚你的出行目的地就行。','zhǐ xū yào jiāo yī zhāng bái dǐ zhèng jiàn zhào ， zài tián xiě qīng chǔ nǐ de chū xíng mù dì dì jiù xíng 。','Chỉ cần nộp một ảnh thẻ nền trắng, rồi ghi rõ điểm đến của bạn là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_07','V515','阮明',7,'了解了。那我再确认一下，高铁乘车、酒店入住这些场景都能用吗？','liǎo jiě le 。 nà wǒ zài què rèn yī xià ， gāo tiě chéng chē 、 jiǔ diàn rù zhù zhè xiē chǎng jǐng dōu néng yòng ma ？','Em hiểu rồi ạ. Cho em xác nhận lại, đi tàu cao tốc, nhận phòng khách sạn có dùng được giấy này không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_08','V515','工作人员',8,'可以的，国内交通出行、住宿登记全部通用，效力等同于临时身份证件。','kě yǐ de ， guó nèi jiāo tōng chū xíng 、 zhù sù dēng jì quán bù tōng yòng ， xiào lì děng tóng yú lín shí shēn fèn zhèng jiàn 。','Được chứ, đi lại trong nước, đăng ký lưu trú đều dùng chung được hết, giá trị tương đương giấy tờ tùy thân tạm thời.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_09','V515','阮明',9,'那等我后续办好居留贴纸、拿回护照的时候，需要把这个临时证明交回来吗？','nà děng wǒ hòu xù bàn hǎo jū liú tiē zhǐ 、 ná huí hù zhào de shí hòu ， xū yào bǎ zhè ge lín shí zhèng míng jiāo huí lái ma ？','Vậy sau này khi em làm xong tem tạm trú, lấy lại hộ chiếu rồi, có cần nộp lại giấy chứng nhận tạm thời này không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_10','V515','工作人员',10,'对，领取正式护照的当天，我们会回收这份纸质临时证明。','duì ， lǐng qǔ zhèng shì hù zhào dí dàng tiān ， wǒ men huì huí shōu zhè fèn zhǐ zhì lín shí zhèng míng 。','Đúng vậy, ngày nhận lại hộ chiếu chính thức, bên mình sẽ thu lại tờ giấy chứng nhận tạm thời này.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_11','V515','阮明',11,'好的，那麻烦您帮我一并办理，这样周末就能正常出行了。','hǎo de ， nà má fán nín bāng wǒ yī bìng bàn lǐ ， zhè yàng zhōu mò jiù néng zhèng cháng chū xíng le 。','Vâng ạ, vậy phiền anh/chị giúp em làm luôn một thể, để cuối tuần em đi lại bình thường ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT516','SV2','中途休学，咨询居留签证暂停与恢复手续',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V516','SIT516','P1','twist','chinh_thuc',NULL,'留学生休学、退学导致学籍失效，学生居留许可自动失效，需在规定缓冲期内离境，滞留会产生行政处罚。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_01','V516','阮明',1,'老师您好，因为身体原因，我打算申请休学半年，想问问我的居留签证要怎么处理？','lǎo shī nín hǎo ， yīn wèi shēn tǐ yuán yīn ， wǒ dǎ suàn shēn qǐng xiū xué bàn nián ， xiǎng wèn wèn wǒ de jū liú qiān zhèng yào zěn me chǔ lǐ ？','Thưa thầy/cô, vì lý do sức khỏe, em định xin bảo lưu nửa năm, cho em hỏi thẻ tạm trú của em phải xử lý thế nào ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_02','V516','老师',2,'是这样的，一旦办理休学，你的在校学籍会直接暂停。','shì zhè yàng de ， yí dàn bàn lǐ xiū xué ， nǐ de zài xiào xué jí huì zhí jiē zàn tíng 。','Là thế này, một khi làm thủ tục bảo lưu, tư cách học sinh tại trường của em sẽ bị tạm dừng ngay.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_03','V516','阮明',3,'那学籍暂停的话，签证还能继续用吗？','nà xué jí zàn tíng de huà ， qiān zhèng hái néng jì xù yòng ma ？','Vậy tư cách học sinh bị tạm dừng thì visa còn dùng được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_04','V516','老师',4,'不能的，学生学籍失效，对应的居留许可也会同步失效，你需要在规定时间内离境。','bù néng de ， xué shēng xué jí shī xiào ， duì yìng de jū liú xǔ kě yě huì tóng bù shī xiào ， nǐ xū yào zài guī dìng shí jiān nèi lí jìng 。','Không được, tư cách học sinh mất hiệu lực thì giấy phép tạm trú tương ứng cũng mất hiệu lực theo, em cần xuất cảnh trong thời gian quy định.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_05','V516','阮明',5,'啊？没办法通融吗？我是身体原因休学，想留在国内休养，不用回国。','a ？ méi bàn fǎ tōng róng ma ？ wǒ shì shēn tǐ yuán yīn xiū xué ， xiǎng liú zài guó nèi xiū yǎng ， bù yòng huí guó 。','Hả? Không có cách nào linh động được ạ? Em bảo lưu vì lý do sức khỏe, muốn ở lại đây dưỡng bệnh, không cần về nước ạ.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_06','V516','老师',6,'我理解你的情况，但政策是统一的。没有有效在校学籍，就不符合学生居留的审批标准，没办法保留签证。','wǒ lǐ jiě nǐ de qíng kuàng ， dàn zhèng cè shì tǒng yī de 。 méi yǒu yǒu xiào zài xiào xué jí ， jiù bù fú hé xué shēng jū liú de shěn pī biāo zhǔn ， méi bàn fǎ bǎo liú qiān zhèng 。','Thầy/cô hiểu hoàn cảnh của em, nhưng chính sách là thống nhất. Không có tư cách học sinh hợp lệ tại trường thì không đủ điều kiện xét duyệt tạm trú diện học sinh, không thể giữ lại visa được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_07','V516','阮明',7,'我明白了。那半年后我复学回来，居留要怎么办理？','wǒ míng bái le 。 nà bàn nián hòu wǒ fù xué huí lái ， jū liú yào zěn me bàn lǐ ？','Em hiểu rồi ạ. Vậy nửa năm sau em quay lại học tiếp thì thủ tục tạm trú phải làm thế nào ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_08','V516','老师',8,'复学之后拿着学校的复学通知书，按照新生的流程，重新全套申请居留许可。','fù xué zhī hòu ná zhe xué xiào de fù xué tōng zhī shū ， àn zhào xīn shēng de liú chéng ， chóng xīn quán tào shēn qǐng jū liú xǔ kě 。','Sau khi quay lại học, em cầm giấy thông báo phục học của trường, làm theo quy trình như sinh viên mới, xin lại toàn bộ giấy phép tạm trú từ đầu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_09','V516','阮明',9,'那我办完休学手续，是不是马上就要离境？有没有缓冲时间？','nà wǒ bàn wán xiū xué shǒu xù ， shì bú shì mǎ shàng jiù yào lí jìng ？ yǒu méi yǒu huǎn chōng shí jiān ？','Vậy làm xong thủ tục bảo lưu là em phải xuất cảnh ngay luôn ạ? Có thời gian đệm nào không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_10','V516','老师',10,'有的，从休学备案当天开始算，有三十天的合法停留期，你可以利用这段时间收拾行李、安排行程。','yǒu de ， cóng xiū xué bèi àn dàng tiān kāi shǐ suàn ， yǒu sān shí tiān de hé fǎ tíng liú qī ， nǐ kě yǐ lì yòng zhè duàn shí jiān shōu shí xíng lǐ 、 ān pái xíng chéng 。','Có chứ, tính từ ngày đăng ký bảo lưu, em có ba mươi ngày lưu trú hợp pháp, có thể tận dụng khoảng thời gian này để thu xếp hành lý, sắp xếp lịch trình.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_11','V516','阮明',11,'清楚了，我会在缓冲期内安排回国休养，不会逾期滞留的。','qīng chǔ le ， wǒ huì zài huǎn chōng qī nèi ān pái huí guó xiū yǎng ， bú huì yú qī zhì liú de 。','Em rõ rồi ạ, em sẽ sắp xếp về nước dưỡng bệnh trong thời gian đệm, không để quá hạn lưu trú đâu ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT517','SV2','短期出境旅游，咨询居留证是否需要备案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V517','SIT517','P1','suon_se','tuy_y',NULL,'持有有效长期学生居留许可，短期出境旅游无需向出入境报备，仅毕业、休学、永久离境才需要注销备案。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_01','V517','阮明',1,'警官，问个事哈，我下周想出国旅游，手里的居留证还在有效期，需要提前报备吗？','jǐng guān ， wèn gè shì hā ， wǒ xià zhōu xiǎng chū guó lǚ yóu ， shǒu lǐ de jū liú zhèng hái zài yǒu xiào qī ， xū yào tí qián bào bèi ma ？','Anh cảnh sát ơi, hỏi tí nha, tuần sau em định đi du lịch nước ngoài, thẻ tạm trú trong tay em vẫn còn hạn, có cần báo trước không ạ?','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_02','V517','辅警',2,'不用不用，短期旅游不用线下备案。','bù yòng bù yòng ， duǎn qī lǚ yóu bù yòng xiàn xià bèi àn 。','Không cần đâu, không cần đâu, đi du lịch ngắn ngày thì không cần đăng ký trực tiếp.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_03','V517','阮明',3,'那我出入境的时候，直接带护照和居留贴纸就行吗？','nà wǒ chū rù jìng de shí hòu ， zhí jiē dài hù zhào hé jū liú tiē zhǐ jiù xíng ma ？','Vậy lúc xuất nhập cảnh, em cứ mang hộ chiếu với tem tạm trú theo là được hả?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_04','V517','辅警',4,'对，两个证件一起给海关查验就行，很方便的。','duì ， liǎng gè zhèng jiàn yì qǐ gěi hǎi guān chá yàn jiù xíng ， hěn fāng biàn de 。','Đúng rồi, đưa hai giấy đó cho hải quan kiểm tra là xong, tiện lắm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_05','V517','阮明',5,'那要是我出去玩得久一点，超过一个月，回来签证会不会出问题？','nà yào shì wǒ chū qù wán dé jiǔ yì diǎn ， chāo guò yí gè yuè ， huí lái qiān zhèng huì bú huì chū wèn tí ？','Vậy nếu em đi chơi lâu hơn một chút, quá một tháng, lúc về visa có bị làm sao không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_06','V517','辅警',6,'没事的，只要你的居留许可没到期，不管出境多久，回来都能正常入境。','méi shì de ， zhǐ yào nǐ de jū liú xǔ kě méi dào qī ， bù guǎn chū jìng duō jiǔ ， huí lái dōu néng zhèng cháng rù jìng 。','Không sao đâu, miễn là giấy phép tạm trú của em chưa hết hạn, đi bao lâu cũng được, về là nhập cảnh bình thường thôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_07','V517','阮明',7,'那就好，我还特意担心要跑一趟大厅报备呢。','nà jiù hǎo ， wǒ hái tè yì dān xīn yào pǎo yī tàng dà tīng bào bèi ne 。','Vậy thì tốt quá, em còn cứ lo phải chạy ra sảnh đăng ký cơ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT518','SV3','护照丢失，派出所开遗失证明用于补办签证',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V518','SIT518','P1','suon_se','chinh_thuc',NULL,'外籍护照遗失必须先到派出所报案获取回执，无回执无法办理临时通行证明、新护照。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_01','V518','阮明',1,'警官您好，我的越南护照不小心弄丢了，想来办理遗失报案，开一份回执证明。','jǐng guān nín hǎo ， wǒ de yuè nán hù zhào bù xiǎo xīn nòng diū le ， xiǎng lái bàn lǐ yí shī bào àn ， kāi yī fèn huí zhí zhèng míng 。','Chào anh công an, hộ chiếu Việt Nam của em lỡ bị mất rồi, em muốn khai báo mất giấy tờ, xin một bản biên nhận ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_02','V518','民警',2,'好的，你仔细说一下具体情况，什么时候丢的、在哪里丢的，当时随身带了哪些东西。','hǎo de ， nǐ zǐ xì shuō yī xià jù tǐ qíng kuàng ， shén me shí hòu diū de 、 zài nǎ lǐ diū de ， dāng shí suí shēn dài le nǎ xiē dōng xī 。','Được, em kể chi tiết xem, mất lúc nào, mất ở đâu, lúc đó mang theo những gì.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_03','V518','阮明',3,'就在昨天下午，我在市区商圈逛街，结账之后发现口袋里的钱包和护照一起不见了。','jiù zài zuó tiān xià wǔ ， wǒ zài shì qū shāng quān guàng jiē ， jié zhàng zhī hòu fā xiàn kǒu dài lǐ de qián bāo hé hù zhào yì qǐ bú jiàn le 。','Là chiều hôm qua ạ, em đi dạo phố mua sắm ở khu trung tâm, thanh toán xong thì phát hiện ví với hộ chiếu trong túi mất luôn cùng lúc.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_04','V518','民警',4,'清楚了，我现在给你录入遗失笔录，信息核对无误签字后，我给你打印两份报案回执。','qīng chǔ le ， wǒ xiàn zài gěi nǐ lù rù yí shī bǐ lù ， xìn xī hé duì wú wù qiān zì hòu ， wǒ gěi nǐ dǎ yìn liǎng fèn bào àn huí zhí 。','Rõ rồi, giờ anh nhập biên bản khai báo mất cho em, sau khi đối chiếu thông tin chính xác và em ký tên xong, anh sẽ in cho em hai bản biên nhận khai báo.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_05','V518','阮明',5,'好的。这两份回执是不是一份用来办临时通行，另一份去大使馆补办新护照？','hǎo de 。 zhè liǎng fèn huí zhí shì bú shì yī fèn yòng lái bàn lín shí tōng xíng ， lìng yī fèn qù dà shǐ guǎn bǔ bàn xīn hù zhào ？','Vâng ạ. Cho em hỏi, hai bản biên nhận này có phải một bản dùng để làm giấy thông hành tạm thời, bản còn lại đem đến đại sứ quán làm lại hộ chiếu mới không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_06','V518','民警',6,'没错，两份用途不一样，你一定要分开保管，千万别再弄丢了。','méi cuò ， liǎng fèn yòng tú bù yí yàng ， nǐ yí dìng yào fēn kāi bǎo guǎn ， qiān wàn bié zài nòng diū le 。','Đúng rồi, hai bản dùng cho hai việc khác nhau, em nhất định phải cất riêng ra, đừng để mất nữa đấy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_07','V518','阮明',7,'我了解了。也就是说，没有这份派出所的回执，所有证件补办手续都办不了是吗？','wǒ liǎo jiě le 。 yě jiù shì shuō ， méi yǒu zhè fèn pài chū suǒ de huí zhí ， suǒ yǒu zhèng jiàn bǔ bàn shǒu xù dōu bàn bù liǎo shì ma ？','Em hiểu rồi ạ. Tức là nếu không có bản biên nhận của công an thì mọi thủ tục làm lại giấy tờ đều không làm được phải không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_08','V518','民警',8,'是的，大使馆和出入境大厅都强制要求提供这份遗失证明，缺一不可。','shì de ， dà shǐ guǎn hé chū rù jìng dà tīng dōu qiáng zhì yāo qiú tí gōng zhè fèn yí shī zhèng míng ， quē yī bù kě 。','Đúng vậy, đại sứ quán và phòng xuất nhập cảnh đều bắt buộc phải có giấy chứng nhận mất này, thiếu là không được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_09','V518','阮明',9,'辛苦您帮忙登记备案，给您添麻烦了。','xīn kǔ nín bāng máng dēng jì bèi àn ， gěi nín tiān má fán le 。','Cảm ơn anh đã giúp em đăng ký khai báo, làm phiền anh nhiều rồi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT519','SV3','居留许可贴纸损毁模糊，申请换发居留贴纸',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V519','SIT519','P1','twist','ban_chinh_thuc',NULL,'居留贴纸磨损、撕毁、信息模糊属于证件损毁，必须换发，旧照片超出半年有效期不能用于新证件办理。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_01','V519','阮明',1,'您好，我想咨询一下，我护照上的居留贴纸磨掉色了，上面的信息都看不清楚，该怎么处理？','nín hǎo ， wǒ xiǎng zī xún yī xià ， wǒ hù zhào shàng de jū liú tiē zhǐ mó diào sè le ， shàng miàn de xìn xī dōu kàn bù qīng chǔ ， gāi zěn me chǔ lǐ ？','Chào anh/chị, em muốn hỏi, tem tạm trú trên hộ chiếu của em bị mòn phai màu, thông tin nhìn không rõ nữa, phải xử lý thế nào ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_02','V519','工作人员',2,'这种属于证件损毁，需要申请换发新的居留许可，先准备一张白底证件照。','zhè zhǒng shǔ yú zhèng jiàn sǔn huǐ ， xū yào shēn qǐng huàn fā xīn de jū liú xǔ kě ， xiān zhǔn bèi yī zhāng bái dǐ zhèng jiàn zhào 。','Trường hợp này thuộc diện giấy tờ bị hư hỏng, cần làm thủ tục cấp lại giấy phép tạm trú mới, trước tiên bạn chuẩn bị một ảnh thẻ nền trắng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_03','V519','阮明',3,'啊，我上次办签证剩下的旧照片还在，用那个可以吗？','a ， wǒ shàng cì bàn qiān zhèng shèng xià de jiù zhào piān hái zài ， yòng nà ge kě yǐ ma ？','À, lần trước làm visa em còn dư ảnh cũ, dùng cái đó được không ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_04','V519','工作人员',4,'不可以的，换发新证件有规定，必须是近六个月新拍的照片，旧照片一律不受理。','bù kě yǐ de ， huàn fā xīn zhèng jiàn yǒu guī dìng ， bì xū shì jìn liù gè yuè xīn pāi de zhào piān ， jiù zhào piān yī lǜ bù shòu lǐ 。','Không được đâu, cấp lại giấy tờ mới có quy định, phải là ảnh chụp mới trong vòng sáu tháng gần đây, ảnh cũ đều không nhận.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_05','V519','阮明',5,'这样啊……那大厅楼下的自助拍照机，能拍符合签证标准的照片吗？','zhè yàng a …… nà dà tīng lóu xià de zì zhù pāi zhào jī ， néng pāi fú hé qiān zhèng biāo zhǔn de zhào piān ma ？','Vậy à... thế máy chụp ảnh tự động ở dưới sảnh có chụp được ảnh đạt chuẩn visa không ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_06','V519','工作人员',6,'可以的，机子拍的都是合规证件照，你拍完直接拿纸质照片回来取号办理就行。','kě yǐ de ， jī zi pāi de dōu shì hé guī zhèng jiàn zhào ， nǐ pāi wán zhí jiē ná zhǐ zhì zhào piān huí lái qǔ hào bàn lǐ jiù xíng 。','Được chứ, máy chụp ra đều là ảnh thẻ đạt chuẩn, bạn chụp xong cầm ảnh giấy quay lại lấy số làm thủ tục luôn là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_07','V519','阮明',7,'好，那我再问一下，办理换发的这段时间，护照要上交吗？','hǎo ， nà wǒ zài wèn yī xià ， bàn lǐ huàn fā de zhè duàn shí jiān ， hù zhào yào shàng jiāo ma ？','Dạ, cho em hỏi thêm, trong thời gian làm thủ tục cấp lại này, có phải nộp hộ chiếu không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_08','V519','工作人员',8,'需要留存七个工作日。这期间如果你有出行需求，记得顺便办一张临时出行证明。','xū yào liú cún qī gè gōng zuò rì 。 zhè qī jiān rú guǒ nǐ yǒu chū xíng xū qiú ， jì de shùn biàn bàn yī zhāng lín shí chū xíng zhèng míng 。','Cần giữ lại bảy ngày làm việc. Trong thời gian này nếu bạn có nhu cầu đi lại, nhớ tiện thể làm luôn một giấy chứng nhận đi lại tạm thời.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_09','V519','阮明',9,'明白了，我现在就去拍照，拍完马上回来递交材料办理换发。','míng bái le ， wǒ xiàn zài jiù qù pāi zhào ， pāi wán mǎ shàng huí lái dì jiāo cái liào bàn lǐ huàn fā 。','Em hiểu rồi ạ, giờ em đi chụp ảnh luôn, chụp xong quay lại nộp hồ sơ làm thủ tục cấp lại ngay.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT520','SV3','护照补办完成后，重新补办在华居留许可',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V520','SIT520','P1','suon_se','chinh_thuc',NULL,'补办护照后不能直接沿用旧居留，必须同步补办居留贴纸，新旧护照搭配使用仅短期有效，长期必须换发居留。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_01','V520','阮明',1,'您好，我已经从大使馆拿到新护照了，现在来补办之前丢失的居留许可。','nín hǎo ， wǒ yǐ jīng cóng dà shǐ guǎn ná dào xīn hù zhào le ， xiàn zài lái bǔ bàn zhī qián diū shī de jū liú xǔ kě 。','Chào anh/chị, em đã lấy được hộ chiếu mới từ đại sứ quán rồi, giờ em đến làm lại giấy phép tạm trú bị mất trước đó ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_02','V520','工作人员',2,'可以的，请递交你的新护照、派出所遗失回执、学校在读证明和住宿登记单。','kě yǐ de ， qǐng dì jiāo nǐ de xīn hù zhào 、 pài chū suǒ yí shī huí zhí 、 xué xiào zài dú zhèng míng hé zhù sù dēng jì dān 。','Được, mời bạn nộp hộ chiếu mới, biên nhận khai báo mất của công an, giấy xác nhận đang học của trường và phiếu đăng ký lưu trú.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_03','V520','阮明',3,'好的。对了，我旧护照过期签证页的复印件，需要一起上交核对吗？','hǎo de 。 duì le ， wǒ jiù hù zhào guò qī qiān zhèng yè de fù yìn jiàn ， xū yào yì qǐ shàng jiāo hé duì ma ？','Vâng ạ. À, bản photo trang visa đã hết hạn trong hộ chiếu cũ có cần nộp kèm để đối chiếu không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_04','V520','工作人员',4,'需要的，复印件我们会留存归档，用来核对你原本的居留有效期限。','xū yào de ， fù yìn jiàn wǒ men huì liú cún guī dàng ， yòng lái hé duì nǐ yuán běn de jū liú yǒu xiào qī xiàn 。','Cần, bản photo bên mình sẽ lưu lại hồ sơ, dùng để đối chiếu thời hạn tạm trú ban đầu của bạn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_05','V520','阮明',5,'了解。那补办的办理时间，和第一次办一样是七个工作日吗？','liǎo jiě 。 nà bǔ bàn de bàn lǐ shí jiān ， hé dì yī cì bàn yī yàng shì qī gè gōng zuò rì ma ？','Em hiểu rồi ạ. Vậy thời gian làm thủ tục cấp lại có giống lần đầu là bảy ngày làm việc không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_06','V520','工作人员',6,'常规流程是七个工作日，如果你着急，也可以走加急通道，三个工作日就能取证。','cháng guī liú chéng shì qī gè gōng zuò rì ， rú guǒ nǐ zháo jí ， yě kě yǐ zǒu jiā jí tōng dào ， sān gè gōng zuò rì jiù néng qǔ zhèng 。','Quy trình thông thường là bảy ngày làm việc, nếu bạn gấp thì cũng có thể làm nhanh, ba ngày làm việc là lấy được giấy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_07','V520','阮明',7,'不用加急，我正常等就行。那补办后的居留有效期，是和我原来剩下的时长一样的吧？','bù yòng jiā jí ， wǒ zhèng cháng děng jiù xíng 。 nà bǔ bàn hòu de jū liú yǒu xiào qī ， shì hé wǒ yuán lái shèng xià de shí cháng yī yàng de ba ？','Không cần gấp đâu ạ, em chờ bình thường cũng được. Vậy giấy phép tạm trú làm lại có thời hạn giống với thời hạn còn lại ban đầu của em đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_08','V520','工作人员',8,'对的，完全同步原来的到期时间，不会重新计算一年有效期。','duì de ， wán quán tóng bù yuán lái de dào qī shí jiān ， bú huì chóng xīn jì suàn yī nián yǒu xiào qī 。','Đúng vậy, hoàn toàn giữ nguyên thời hạn hết hạn ban đầu, không tính lại một năm mới đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_09','V520','阮明',9,'没问题，我材料都齐了，麻烦您帮我受理一下。','méi wèn tí ， wǒ cái liào dōu qí le ， má fán nín bāng wǒ shòu lǐ yī xià 。','Không vấn đề gì ạ, hồ sơ em đã đủ cả rồi, phiền anh/chị giúp em tiếp nhận xử lý ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT521','SV3','出境紧急情况无证件，申请出入境临时通行纸',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V521','SIT521','P1','twist','chinh_thuc',NULL,'临时出入境通行证明仅限单次出境，不可用于再次入境中国，回国后需在本国驻华使馆补办正式护照。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_01','V521','阮明',1,'警官，麻烦您帮帮忙！我明天一早的航班要回国，但是护照丢了，急需办一个临时通行证件。','jǐng guān ， má fán nín bāng bāng máng ！ wǒ míng tiān yī zǎo de háng bān yào huí guó ， dàn shì hù zhào diū le ， jí xū bàn yí gè lín shí tōng xíng zhèng jiàn 。','Anh công an ơi, làm ơn giúp em với! Sáng sớm mai em có chuyến bay về nước, nhưng hộ chiếu bị mất rồi, em cần gấp một giấy thông hành tạm thời ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_02','V521','民警',2,'别着急，先把派出所的遗失回执给我，我核对一下你的备案信息。','bié zháo jí ， xiān bǎ pài chū suǒ de yí shī huí zhí gěi wǒ ， wǒ hé duì yī xià nǐ de bèi àn xìn xī 。','Đừng lo, trước tiên đưa anh biên nhận khai báo mất của công an, anh kiểm tra thông tin đăng ký của em đã.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_03','V521','阮明',3,'回执我带在身上了！但是我刚刚去拍照，自助机已经关门了，没有纸质照片怎么办？','huí zhí wǒ dài zài shēn shàng le ！ dàn shì wǒ gāng gāng qù pāi zhào ， zì zhù jī yǐ jīng guān mén le ， méi yǒu zhǐ zhì zhào piān zěn me bàn ？','Biên nhận em mang theo người rồi ạ! Nhưng em vừa mới đi chụp ảnh thì máy tự động đã đóng cửa, không có ảnh giấy thì phải làm sao ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_04','V521','民警',4,'没关系，你是紧急出境情况，可以免交纸质照片，我们系统里有你之前留存的证件照，可以直接调取使用。','méi guān xì ， nǐ shì jǐn jí chū jìng qíng kuàng ， kě yǐ miǎn jiāo zhǐ zhì zhào piān ， wǒ men xì tǒng lǐ yǒu nǐ zhī qián liú cún de zhèng jiàn zhào ， kě yǐ zhí jiē diào qǔ shǐ yòng 。','Không sao, trường hợp em xuất cảnh khẩn cấp thì được miễn nộp ảnh giấy, hệ thống bên anh có lưu ảnh thẻ trước đây của em, có thể lấy trực tiếp để dùng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_05','V521','阮明',5,'太好了，谢谢您！那我确认一下，这张临时通行纸只能这次出境用，不能再入境中国了对吧？','tài hǎo le ， xiè xiè nín ！ nà wǒ què rèn yī xià ， zhè zhāng lín shí tōng xíng zhǐ zhǐ néng zhè cì chū jìng yòng ， bù néng zài rù jìng zhōng guó le duì ba ？','Tuyệt quá, cảm ơn anh! Cho em xác nhận lại, tờ giấy thông hành tạm thời này chỉ dùng để xuất cảnh lần này thôi, không thể dùng để nhập cảnh lại Trung Quốc nữa đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
